package com.ecommerce.order; import com.ecommerce.product.Product; import com.ecommerce.seller.SellerProfile; import jakarta.persistence.*; import java.math.BigDecimal; import java.util.UUID;
@Entity @Table(name="order_items") public class OrderItem { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="order_id",nullable=false) Order order; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="product_id",nullable=false) Product product; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="seller_id",nullable=false) SellerProfile seller; @Column(nullable=false) int quantity; @Column(nullable=false,precision=12,scale=2) BigDecimal price; public Product getProduct(){return product;} public int getQuantity(){return quantity;} public BigDecimal getPrice(){return price;} public void setOrder(Order v){order=v;} public void setProduct(Product v){product=v;} public void setSeller(SellerProfile v){seller=v;} public void setQuantity(int v){quantity=v;} public void setPrice(BigDecimal v){price=v;} }
